// BFME PartitionFilter linked-list append. ZH filters were a NULL-terminated
// array; retail walks m_next at +4 and writes the supplied filter on the tail.

class Object;

class PartitionFilter
{
public:
	virtual bool allow(Object *object) = 0;
	PartitionFilter *link(PartitionFilter *next);
	PartitionFilter *m_next;
};

PartitionFilter *PartitionFilter::link(PartitionFilter *next)
{
	PartitionFilter *cursor = 0;
	PartitionFilter *candidate = m_next;
	if (candidate != 0)
	{
		do
		{
			cursor = candidate;
			candidate = *(PartitionFilter **)(4 + (unsigned int)cursor);
		}
		while (candidate != 0);
		cursor->m_next = next;
	}
	else
	{
		m_next = next;
	}
	return this;
}
